create or replace function public.accept_gig(p_offer bigint)
returns public.gig_offers
language plpgsql security definer set search_path = public
as $$
declare
  uid uuid := auth.uid();
  o public.gig_offers;
  me public.players;
begin
  perform public.tick(uid);
  select * into me from public.players where id = uid for update;
  select * into o from public.gig_offers where id = p_offer and player_id = uid for update;
  if o.id is null then raise exception 'unknown_gig' using errcode = '22023'; end if;
  if o.ny_date <> public.ny_today() then raise exception 'gig_expired' using errcode = '22023'; end if;
  if o.accepted_at is not null then return o; end if;
  if exists (select 1 from public.gig_offers where player_id = uid and accepted_at is not null and collected_at is null) then
    raise exception 'gig_active' using errcode = '22023';
  end if;
  if me.clout < coalesce((public.city() -> 'economy' -> 'gigs' -> o.tier ->> 'clout')::int, 0) then
    raise exception 'needs_clout' using errcode = '22023';
  end if;
  if me.confidence < o.confidence_req then raise exception 'needs_confidence' using errcode = '22023'; end if;
  if me.energy < o.energy then raise exception 'no_energy' using errcode = '22023'; end if;
  update public.players set energy = energy - o.energy where id = uid;
  update public.gig_offers set accepted_at = public.game_now(), ready_at = public.game_now() + make_interval(mins => o.wait_minutes)
   where id = o.id returning * into o;
  return o;
end;
$$;

create or replace function public.player_card(p_player uuid)
returns jsonb
language sql stable security definer set search_path = public
as $$
  select jsonb_build_object(
    'id', p.id, 'name', p.display_name, 'style', p.starting_style, 'clout', p.clout, 'homeId', p.home_id,
    'badges', (select count(*) from public.player_badges b where b.player_id = p.id),
    'joined', p.created_at,
    'blocked', exists (select 1 from public.blocks k where k.blocker = auth.uid() and k.blocked = p.id),
    'isMe', p.id = auth.uid(),
    'crush', case when p.id <> auth.uid() then public.crush_status(p.id) end,
    -- Same order as the Queens leaderboard (leaderboard_people): clout, then who arrived first.
    'rank', 1 + (select count(*) from public.players o
                  where o.banned_at is null
                    and (o.clout > p.clout or (o.clout = p.clout and o.created_at < p.created_at))),
    'recent', public.player_recent(p.id, 5),
    -- v0.7: net worth is public on the card (owner, Oct 13): bank cash plus what they own, the same
    -- sum the player's own Net Worth screen shows (lib/cityState.ts netWorth).
    'netWorth', p.bank_cash + coalesce((select sum(i.value) from public.player_items i where i.player_id = p.id), 0))
  from public.players p where p.id = p_player and p.banned_at is null and p.home_id is not null;
$$;
